import java.io.*;
import java.util.*;

// Stand-in for the given Main.class (javap -c): it asks for the path FIRST, uses println for every prompt
class Main {
    public static void main(String[] args) {
        MyFile f = new MyFile();
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter file path:");
        String path = sc.nextLine();
        System.out.println("1. Test f1");
        System.out.println("2. Test f2");
        System.out.println("your choice:");
        int tc = sc.nextInt();
        sc.nextLine();
        System.out.println("OUTPUT:");
        switch (tc) {
            case 1: System.out.println(f.f1(path)); break;
            case 2: System.out.println(f.f2(path)); break;
        }
    }
}
